import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    base = os.path.basename(filename)
    if not base:
        raise ValueError("Filename cannot be empty")
    path = os.path.join(upload_dir, base)
    if not os.path.commonprefix([upload_dir, path]) == upload_dir:
        raise ValueError("Filename contains path traversal attempt")
    return os.path.abspath(path)
